gRR(){return"\u0414\u0430. \u0412 \u043d\u0430\u0447\u0430\u043b\u0435 \u0443\u0447\u0430\u0441\u0442\u043a\u0430 \u0437\u043d\u0430\u043a \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0434\u043e \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u0433\u043e \u043f\u0435\u0440\u0435\u043a\u0440\u0451\u0441\u0442\u043a\u0430, \u043d\u043e \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u043d\u0430\u043f\u0440\u0430\u0432\u043e \u043d\u0430 \u043f\u0440\u0438\u043b\u0435\u0433\u0430\u044e\u0449\u0443\u044e \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u044e."},
gRU(){return"\u0417\u043d\u0430\u043a \u0441\u0442\u043e\u0438\u0442 \u043f\u0435\u0440\u0435\u0434 \u043f\u0435\u0440\u0435\u043a\u0440\u0451\u0441\u0442\u043a\u043e\u043c. \u041c\u043e\u0436\u043d\u043e \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u044c \u043d\u0430\u043b\u0435\u0432\u043e?"},
gRT(){return"\u041d\u0435\u0442. \u041d\u0430 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u043c \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u043f\u0440\u043e\u0435\u0437\u0436\u0438\u0445 \u0447\u0430\u0441\u0442\u0435\u0439 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u044f\u043c\u043e."},
gRW(){return"\u041d\u0430 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u043c \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u043d\u0443\u0436\u043d\u043e \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u044c \u043d\u0430\u043f\u0440\u0430\u0432\u043e?"},
gRV(){return"\u0414\u0430. \u0414\u043b\u044f \u043e\u0431\u044b\u0447\u043d\u043e\u0433\u043e \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u044f \u0437\u043d\u0430\u043a \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u043d\u0430\u043f\u0440\u0430\u0432\u043e."},
gRY(){return u.y},
gRX(){return"\u041d\u0435\u0442. \u0417\u043d\u0430\u043a \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043e."},
gS_(){return"\u042d\u0442\u043e\u0442 \u0437\u043d\u0430\u043a \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0440\u0430\u0437\u0432\u043e\u0440\u043e\u0442?"},
gRZ(){return"\u0414\u0430. \u0417\u043d\u0430\u043a, \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u044e\u0449\u0438\u0439 \u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u043d\u0430\u043b\u0435\u0432\u043e, \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0438 \u0440\u0430\u0437\u0432\u043e\u0440\u043e\u0442."},
gS1(){return u.y},
gS0(){return"\u041d\u0435\u0442. \u0417\u043d\u0430\u043a \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u043d\u0430\u043b\u0435\u0432\u043e \u0438 \u0440\u0430\u0437\u0432\u043e\u0440\u043e\u0442."},
gS3(){return"\u041c\u043e\u0436\u043d\u043e \u0435\u0445\u0430\u0442\u044c \u043f\u0440\u044f\u043c\u043e \u0438\u043b\u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043e?"},
gS2(){return"\u0414\u0430. \u0417\u043d\u0430\u043a \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u043e\u0431\u0430 \u044d\u0442\u0438\u0445 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f."},
gS5(){return"\u041c\u043e\u0436\u043d\u043e \u0440\u0430\u0437\u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u043d\u0430 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u043c \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438?"},
gS4(){return"\u041d\u0435\u0442. \u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u044b \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u044f\u043c\u043e \u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043e."},
